def extras(a, family):
    import itertools
    qs = [a[:, i] + sign * a[:, j] for (i, j) in itertools.combinations(range(4), 2) for sign in (-1, 1)]
    if family == 'signed_pair':
        return np.column_stack([q * abs(q) for q in qs])
    return np.column_stack([q ** 3 / (1 + q * q) for q in [*a.T, *qs]])

def _bridge(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack((np.ones(len(raw)), raw)), cal['true_channel_loads'], rcond=None)[0]

def _loads(block, bridge):
    total = bridge.sum(axis=1)
    return tuple((block[key] @ total[1:] + total[0] for key in ('past_channel_raw', 'hold_channel_raw')))
